# C1 bank growth: B2 grammar (+76). Kid/teen topics; rule + example and a "why not" note for every wrong option.
from c1_grow import m
B2G = [
 # third / mixed conditionals
 m("If we ___ the map, we wouldn't have got lost in the maze.", "had checked", ["checked", "would check", "have checked"], "Third conditional (imaginary past): If + had + past participle, would have + past participle. Example: If I had known, I would have come.", ["Checked is second conditional (present/future), but this is about the past.", "Would never goes in the if-clause.", "Have checked is present perfect, not the past perfect we need."]),
 m("If the robot ___ properly, we would have won the science fair.", "had worked", ["worked", "would work", "has worked"], "Third conditional: If + past perfect for an imaginary past. Example: If it had rained, we'd have stayed in.", ["Worked makes it a present/future situation.", "Would doesn't go in the if-clause.", "Has worked is present perfect."]),
 m("She would have caught the bus if she ___ up earlier.", "had got", ["got", "would get", "has got"], "Third conditional: the if-clause uses had + past participle. Example: if she had left earlier…", ["Got is second conditional.", "No would in the if-clause.", "Has got is present."]),
 m("If I hadn't stayed up gaming, I ___ so tired now.", "wouldn't be", ["wouldn't have been", "won't be", "hadn't been"], "Mixed conditional: past cause (had + p.p.) → present result (would + verb). Example: If I'd eaten breakfast, I wouldn't be hungry now.", ["Wouldn't have been talks about the past, but 'now' shows the present.", "Won't is for real future possibilities.", "Hadn't been belongs in the if-clause, not the result."]),
 m("If she were braver, she ___ for the lead role last week.", "would have auditioned", ["would audition", "had auditioned", "auditioned"], "Mixed conditional: present state (were) → past result (would have + p.p.). Example: If I were taller, I'd have joined the team last year.", ["Would audition is present/future, but 'last week' is past.", "Had auditioned belongs in an if-clause.", "Auditioned is a real past fact, not imaginary."]),
 m("___ you need any help with the project, just send me a message.", "Should", ["Would", "Had", "Were"], "Should at the start = 'if' for a possible future need (formal). Example: Should you have questions, ask me.", ["Would can't replace if.", "Had + you is for imaginary past: Had you known…", "Were you is followed by to-infinitive or an adjective, not need."]),
 m("___ I known the test was today, I'd have revised.", "Had", ["If", "Were", "Should"], "Inverted third conditional: Had + subject + p.p. = If + had. Example: Had we left earlier, we'd have caught it.", ["If would need had too: If I had known.", "Were I is for present imaginary situations.", "Should is for possible future events."]),
 m("I'll lend you my scooter ___ you're careful with it.", "as long as", ["unless", "in case", "even if"], "As long as = only if. Example: You can play as long as you finish your homework.", ["Unless means if not, the opposite meaning.", "In case = because something might happen.", "Even if = whether or not, which doesn't make it a condition."]),
 m("___ it rains, the sports day will go ahead.", "Even if", ["Unless", "Provided", "As long as"], "Even if = whatever happens, the result stays the same. Example: Even if I'm tired, I'll finish.", ["Unless would mean it only goes ahead if it doesn't rain.", "Provided means only if it rains, which is odd.", "As long as makes rain a requirement."]),
 m("But for your help, I ___ the puzzle.", "wouldn't have finished", ["didn't finish", "won't finish", "hadn't finished"], "But for + noun = if it hadn't been for. Example: But for the map, we'd have got lost.", ["Didn't finish is a real fact, not imaginary.", "Won't is for real future events.", "Hadn't finished needs to be in an if-clause."]),
 # wishes / regrets
 m("I wish I ___ to the concert last night. Everyone says it was amazing.", "had gone", ["went", "would go", "have gone"], "Wish + past perfect = regret about the past. Example: I wish I had studied more.", ["Went after wish is for the present.", "Would after wish is for annoying habits or wanting change.", "Have gone is present perfect; wish needs the past perfect."]),
 m("I wish I ___ play the guitar. It looks so fun.", "could", ["can", "will", "am able"], "Wish + could = an ability you'd like to have now. Example: I wish I could fly.", ["Can doesn't go after wish.", "Will doesn't go after wish.", "Am able needs to and isn't used after wish."]),
 m("I wish my little brother ___ touching my things!", "would stop", ["stops", "stopped to", "will stop"], "Wish + would = annoyance at someone's behaviour. Example: I wish you would listen.", ["Stops (present) doesn't follow wish.", "Stopped to means stopped in order to.", "Will doesn't follow wish."]),
 m("If only we ___ more time to finish the castle model!", "had", ["have", "would have", "will have"], "If only + past = a wish about now. Example: If only it were Saturday!", ["Have is present; after if only we step back to the past.", "Would have is for past results.", "Will have is future."]),
 m("It's time you ___ to bed. It's nearly eleven!", "went", ["go", "will go", "going"], "It's (high) time + past simple = you should do it now. Example: It's time we left.", ["Go isn't used after it's time + subject.", "Will doesn't follow it's time.", "Going isn't a full verb here."]),
 m("I'd rather you ___ my diary. It's private.", "didn't read", ["don't read", "not read", "won't read"], "I'd rather + person + past simple = what I want someone else to do. Example: I'd rather you stayed.", ["Don't read is present, but this pattern needs the past.", "Not read is missing did.", "Won't doesn't follow I'd rather."]),
 # modals of deduction / past modals
 m("The lights are off. They ___ gone to bed already.", "must have", ["can't have", "should", "must"], "Must have + p.p. = I'm sure it happened. Example: She must have left.", ["Can't have means I'm sure it didn't happen.", "Should is advice, and needs 'have gone' anyway.", "Must gone is missing have."]),
 m("He ___ seen the ghost. Ghosts aren't real!", "can't have", ["mustn't have", "must have", "couldn't"], "Can't have + p.p. = I'm sure it didn't happen. Example: She can't have eaten it all!", ["Mustn't isn't used for deduction in British English.", "Must have means you're sure it did happen.", "Couldn't seen is missing have."]),
 m("I'm not sure where my phone is. I ___ left it on the bus.", "might have", ["must", "should have", "can have"], "Might/may/could have + p.p. = perhaps it happened. Example: He might have forgotten.", ["Must left is missing have, and must is too sure.", "Should have means it was the right thing to do.", "Can have isn't used for past possibility."]),
 m("You ___ told me about the test! I didn't revise at all.", "should have", ["must have", "could", "had to"], "Should have + p.p. = criticism of a past action. Example: You should have asked.", ["Must have is deduction, not criticism.", "Could told is missing have.", "Had to told isn't a form."]),
 m("We ___ taken umbrellas. It didn't rain after all.", "needn't have", ["mustn't have", "didn't need", "shouldn't"], "Needn't have + p.p. = we did it, but it wasn't necessary. Example: I needn't have worried.", ["Mustn't have isn't a past modal for necessity.", "Didn't need taken is wrong: didn't need to take.", "Shouldn't taken is missing have."]),
 m("She ___ be at home. Her bike's outside.", "must", ["can't", "might not", "needn't"], "Must = I'm sure (present deduction). Example: You must be tired after the race.", ["Can't means you're sure she isn't.", "Might not doesn't match the clue of the bike.", "Needn't is about necessity, not deduction."]),
 m("The test ___ be that hard; everyone finished early.", "can't", ["mustn't", "must", "should"], "Can't = I'm sure it isn't true. Example: That can't be right.", ["Mustn't is a rule, not a deduction.", "Must would mean you're sure it was hard.", "Should is advice or expectation."]),
 # passive structures
 m("The new skate park ___ at the moment.", "is being built", ["is building", "has been building", "builds"], "Present continuous passive: is/are being + p.p. Example: The road is being repaired.", ["Is building makes the park the builder.", "Has been building is active.", "Builds is active present simple."]),
 m("The winners ___ by the time we arrived.", "had already been chosen", ["had already chosen", "have already been chosen", "were already choosing"], "Past perfect passive: had been + p.p. Example: The cake had been eaten.", ["Had chosen is active: the winners chose something.", "Have been is present perfect, but 'arrived' is past.", "Were choosing is active."]),
 m("The dinosaur bones are said ___ 70 million years old.", "to be", ["being", "be", "to have"], "Be said/thought/believed + to-infinitive. Example: He is said to be very kind.", ["Being doesn't follow are said.", "We need to before be.", "To have would need a past participle."]),
 m("The pyramids are thought ___ by thousands of workers.", "to have been built", ["to be built", "to have built", "being built"], "Passive report about the past: to have been + p.p. Example: The castle is believed to have been built in 1200.", ["To be built is about now or the future.", "To have built is active: the pyramids built something.", "Being built doesn't follow are thought."]),
 m("It ___ that the comet will be visible on Friday.", "is expected", ["expects", "is expecting", "expected"], "It + is + reporting verb (passive) + that. Example: It is believed that he left.", ["Expects is active and needs a subject who expects.", "Is expecting is active.", "Expected alone is missing is."]),
 m("I'm having my bedroom ___ next week.", "painted", ["paint", "to paint", "painting"], "Have something done = someone else does it for you. Example: I had my hair cut.", ["Paint is the base form; we need the past participle.", "To paint doesn't follow have + object here.", "Painting would mean the room is doing the painting."]),
 m("She got her phone screen ___ after she dropped it.", "repaired", ["repair", "repairing", "to repair"], "Get something done = arrange for someone to do it. Example: We got the car washed.", ["Repair is the base form.", "Repairing doesn't fit get + object here.", "To repair doesn't fit this pattern."]),
 m("The match ___ because of the storm.", "had to be cancelled", ["had to cancel", "must cancel", "has cancelled"], "Modal passive: modal + be + p.p. Example: The homework must be finished.", ["Had to cancel is active: the match cancelled something.", "Must cancel is active and present.", "Has cancelled is active."]),
 # reported speech advanced
 m("The coach ___ us to warm up properly.", "reminded", ["said", "suggested", "explained"], "Remind/tell/ask + person + to-infinitive. Example: She reminded me to bring my kit.", ["Say doesn't take a person + to: said to us that…", "Suggest isn't followed by person + to.", "Explain isn't followed by person + to."]),
 m("Ella suggested ___ a film instead.", "watching", ["to watch", "us to watch", "watch"], "Suggest + -ing (or that + subject + verb). Example: He suggested going home.", ["Suggest isn't followed by to-infinitive.", "Suggest isn't followed by person + to.", "Watch needs -ing or that we watch."]),
 m("He apologised ___ late for rehearsal.", "for being", ["to be", "being", "that being"], "Apologise for + -ing. Example: She apologised for shouting.", ["Apologise isn't followed by to-infinitive.", "We need the preposition for.", "That being isn't a correct pattern."]),
 m("My friend admitted ___ the last cookie.", "eating", ["to eating it", "to eat", "eat"], "Admit + -ing (or admit to + -ing). Example: He admitted breaking the vase.", ["The it repeats the object: the last cookie.", "Admit isn't followed by to-infinitive.", "Eat needs -ing."]),
 m("She asked me where ___.", "the library was", ["was the library", "is the library", "the library is it"], "Reported questions use statement word order and backshift. Example: He asked what time it was.", ["Was the library is question order.", "Is the library is question order and present.", "It is extra."]),
 m("Our teacher warned us ___ the electric fence.", "not to touch", ["to not touching", "don't touch", "not touching"], "Warn + person + not to + verb. Example: She warned me not to be late.", ["To not touching mixes two forms.", "Don't touch is direct speech.", "Warn + person needs the to-infinitive."]),
 m("He accused his brother ___ his headphones.", "of breaking", ["for breaking", "to break", "about breaking"], "Accuse someone of + -ing. Example: They accused him of cheating.", ["Accuse goes with of, not for.", "Accuse isn't followed by to-infinitive.", "Accuse goes with of, not about."]),
 # gerund/infinitive meaning changes
 m("I'll never forget ___ the northern lights for the first time.", "seeing", ["to see", "see", "to have seen"], "Forget + -ing = a memory of the past. Example: I'll never forget meeting her.", ["Forget to see = not remember to do it.", "We need -ing.", "To have seen doesn't follow forget here."]),
 m("Don't forget ___ the hamster before you leave.", "to feed", ["feeding", "feed", "fed"], "Forget + to-infinitive = not remember to do a task. Example: Don't forget to lock the door.", ["Forget feeding is about a past memory.", "We need to before feed.", "Fed is past."]),
 m("He tried ___ the lid, but it was stuck.", "to open", ["opening", "open", "to opening"], "Try + to = make an effort (it's difficult). Example: I tried to lift it.", ["Try + -ing = do it as an experiment to see if it helps.", "We need to before open.", "To opening isn't a form here."]),
 m("If the plant looks sad, try ___ it some water.", "giving", ["to give", "give", "to giving"], "Try + -ing = do something as an experiment. Example: Try restarting the computer.", ["Try to give = make an effort, but giving water isn't difficult.", "We need -ing.", "To giving isn't a form here."]),
 m("After the maths lesson, we went on ___ the science project.", "to do", ["doing", "do", "to doing"], "Go on + to = move on to something new. Example: She went on to become a pilot.", ["Go on doing = continue the same thing.", "We need to.", "To doing isn't a form here."]),
 m("I regret ___ so rude to my friend yesterday.", "being", ["to be", "be", "been"], "Regret + -ing = be sorry about the past. Example: I regret saying that.", ["Regret to = formal: I'm sorry to tell you.", "We need -ing.", "Been needs have."]),
 m("She's used to ___ up early for swim training.", "getting", ["get", "got", "to get"], "Be used to + -ing = be familiar with. Example: I'm used to living here.", ["After be used to we need -ing.", "Got is past.", "Used to get (no be) is a past habit."]),
 m("I'd prefer ___ at home tonight.", "to stay", ["staying", "stay", "stayed"], "Would prefer + to-infinitive. Example: I'd prefer to walk.", ["Prefer -ing is for general likes, not 'would prefer'.", "We need to.", "Stayed is past."]),
 m("The joke was so funny that I couldn't stop ___.", "laughing", ["to laugh", "laugh", "laughed"], "Stop + -ing = finish doing. Example: Stop talking!", ["Stop to laugh = stop in order to laugh.", "We need -ing.", "Laughed is past."]),
 # relative clauses advanced
 m("The planet, ___ is the largest in our solar system, has a giant storm.", "which", ["that", "who", "what"], "Non-defining relative clauses (with commas) use which, not that. Example: My bike, which is red, is new.", ["That can't be used after a comma.", "Who is for people.", "What can't be a relative pronoun here."]),
 m("The scientist ___ invention we tested is coming to our school.", "whose", ["who", "which", "who's"], "Whose = belonging to. Example: The girl whose dog barks.", ["Who would need 'her invention'.", "Which is for things.", "Who's = who is."]),
 m("This is the spot ___ we found the fossil.", "where", ["which", "that", "what"], "Where = in/at which (place). Example: The town where I grew up.", ["Which would need a preposition: in which.", "That would need 'at' at the end.", "What isn't a relative pronoun."]),
 m("The friend ___ I told my secret kept it safe.", "to whom", ["whom", "to who", "which"], "Preposition + whom (formal). Example: The person to whom I spoke.", ["Tell someone something needs to: told it to whom.", "After a preposition we use whom, not who.", "Which is for things."]),
 m("He failed the test, ___ surprised everyone.", "which", ["that", "what", "who"], "Which can refer to a whole clause. Example: She laughed, which annoyed him.", ["That can't follow a comma.", "What can't refer back to a clause.", "Who is for people."]),
 m("I have three cousins, all of ___ live in Canada.", "whom", ["who", "them", "which"], "Quantifier + of + whom/which. Example: two dogs, both of which bark.", ["After of we need whom.", "Them would make two sentences joined by a comma.", "Which is for things."]),
 # participle clauses
 m("___ the door, she saw a huge cake on the table.", "Opening", ["Opened", "Having open", "To opening"], "Present participle clause: two actions by the same person, one after the other. Example: Walking home, I saw a fox.", ["Opened is passive: the door opened her.", "Having open is missing -ed: having opened.", "To opening isn't a form."]),
 m("___ his homework, Leo went out to play.", "Having finished", ["Finished", "Being finished", "Have finished"], "Having + p.p. = one action completed before another. Example: Having eaten, we left.", ["Finished alone sounds passive.", "Being finished is passive.", "Have finished isn't a participle."]),
 m("___ in 1903, the first plane flew for only 12 seconds.", "Built", ["Building", "Having built", "To build"], "Past participle clause = passive meaning. Example: Made of glass, the vase broke.", ["Building would mean the plane was building something.", "Having built is active.", "To build means purpose."]),
 m("The boy ___ next to me is my cousin.", "sitting", ["sat down", "who sitting", "sits"], "Reduced relative clause: noun + -ing = who is doing. Example: The girl wearing red.", ["Sat down would need 'who': who sat down.", "Who sitting is missing is.", "Sits needs who before it."]),
 # inversion (B2 level)
 m("Never ___ such a beautiful sunset.", "have I seen", ["I have seen", "I saw", "seen I have"], "Negative adverb first → inversion. Example: Never have I been so tired.", ["After never we invert: have I.", "Past simple would need did I see.", "Seen I have is wrong word order."]),
 m("Not only ___ the race, but she also broke the record.", "did she win", ["she won", "won she", "she did win"], "Not only + inversion, but also… Example: Not only is it fast, but it's also cheap.", ["After not only we invert.", "Won she isn't English.", "She did win is normal order."]),
 m("No sooner had we sat down ___ the fire alarm went off.", "than", ["when", "then", "that"], "No sooner … than. Example: No sooner had I left than it rained.", ["When goes with hardly/scarcely.", "Then isn't used in this pattern.", "That doesn't follow no sooner."]),
 m("Hardly ___ the lights gone out when the ghost story began.", "had", ["have", "did", "were"], "Hardly + had + subject + p.p. + when. Example: Hardly had I arrived when it started.", ["Have is present perfect; the story is in the past.", "Did needs a base verb.", "Were doesn't go with gone here."]),
 # future forms
 m("This time next week, we ___ on the beach in Bali!", "will be lying", ["will lie", "are lying", "will have lain"], "Future continuous: an action in progress at a future time. Example: At 8, I'll be eating.", ["Will lie is one action, not in progress.", "Are lying would be a fixed plan, but we need in-progress.", "Will have lain = finished by then."]),
 m("By the end of term, I ___ ten books for the reading challenge.", "will have read", ["will read", "am reading", "will be reading"], "Future perfect: done before a future time. Example: By 6, I'll have finished.", ["Will read doesn't show completion by a time.", "Am reading is now.", "Will be reading is in progress, not completed."]),
 m("The train ___ at 7:15 tomorrow, so don't be late.", "leaves", ["will be leaving", "is going to leave", "has left"], "Present simple for timetables. Example: The film starts at 8.", ["Will be leaving is possible but less natural for a timetable.", "Going to is for plans or predictions, not timetables.", "Has left is present perfect."]),
 m("Look at those clouds! It ___ pour any minute.", "is about to", ["will be", "is due", "is on"], "Be about to = very soon. Example: The film is about to start.", ["Will be pour isn't a form.", "Is due to needs to.", "Is on isn't a future form."]),
 m("We ___ to visit the space museum, but it was closed.", "were going", ["are going", "will go", "go"], "Was/were going to = a past plan that didn't happen. Example: I was going to call, but I forgot.", ["Are going is a present plan, but it was closed.", "Will go is future.", "Go is present."]),
 # articles/quantifiers/linkers (B2)
 m("___ the fact that it was raining, we played outside.", "Despite", ["Although", "However", "Even though"], "Despite + noun/-ing. Example: Despite the cold, we swam.", ["Although needs a clause: although it was raining.", "However starts a new sentence.", "Even though needs a subject + verb: even though it was raining."]),
 m("He's ___ talented that he could play for the national team.", "so", ["such", "too", "very"], "So + adjective + that. Example: It was so cold that we stayed in.", ["Such needs a noun: such a talented player.", "Too + adjective means more than enough.", "Very doesn't go with that."]),
 m("It was ___ an exciting match that nobody left early.", "such", ["so", "too", "very"], "Such + (a/an) + adjective + noun + that. Example: She's such a good friend.", ["So doesn't go before a/an + noun.", "Too doesn't fit with a noun here.", "Very doesn't go before an."]),
 m("There's ___ time left, so hurry up!", "little", ["few", "a few", "many"], "Little + uncountable (not much). Example: There's little milk.", ["Few is for countable nouns.", "A few is for countable nouns.", "Many is for countable nouns."]),
 m("___ of my friends likes horror films; they all hate them.", "None", ["Neither", "No one", "Nothing"], "None of + plural group = not one. Example: None of the cakes are left.", ["Neither is only for two people.", "No one can't be followed by of.", "Nothing is for things, not friends."]),
 m("You can borrow ___ book. I like them both.", "either", ["neither", "both", "any of"], "Either + singular noun = one or the other of two. Example: Either day is fine.", ["Neither would mean you can't borrow one.", "Both needs a plural noun.", "Any of needs the: any of the books."]),
 m("I'll finish the poster ___ Friday at the latest.", "by", ["until", "since", "for"], "By + time = no later than. Example: Hand it in by Monday.", ["Until means continuing up to then.", "Since is for a starting point.", "For is for a period of time."]),
 m("We waited ___ midnight to see the meteor shower.", "until", ["by", "since", "during"], "Until = continuing up to a time. Example: I'll wait until six.", ["By = no later than, not continuing.", "Since is for a starting point in the past.", "During needs a period: during the night."]),
 m("We've lived here ___ I was six.", "since", ["for", "from", "ago"], "Since + a point in time with present perfect. Example: since 2020.", ["For is for a length of time.", "From needs to/until.", "Ago follows a time: two years ago."]),
 m("The test was hard. ___, most of us passed.", "Nevertheless", ["Despite", "Although", "Because"], "Nevertheless = however, at the start of a new sentence. Example: It rained. Nevertheless, we went.", ["Despite needs a noun after it.", "Although joins two clauses in one sentence.", "Because gives a reason, not contrast."]),
 m("I'll take some snacks ___ we get hungry on the hike.", "in case", ["so that", "unless", "otherwise"], "In case = as a precaution because it might happen. Example: Take a coat in case it's cold.", ["So that shows purpose, and needs a different verb.", "Unless means if not.", "Otherwise means if not, and needs a comma clause."]),
 m("She practised every day ___ win the competition.", "so as to", ["so that", "in case", "for to"], "So as to / in order to + verb = purpose. Example: I left early so as to catch the bus.", ["So that needs a subject: so that she could win.", "In case is a precaution, not a purpose.", "For to isn't English."]),
]
